-- 00:25: detach (brief lock at end, CONCURRENTLY)
ALTER TABLE recon.fact_leg DETACH PARTITION recon.fact_leg_p20220408 CONCURRENTLY;

-- 22:30: move to cold. This is COPY under the hood. Monitor pg_stat_progress_copy.
ALTER TABLE recon.fact_leg_p20220408 SET TABLESPACE tbs_recon_cold;
ALTER INDEX recon.fact_leg_p20220408_pkey SET TABLESPACE tbs_recon_cold;
ALTER INDEX recon.uq_fact_leg_p20220408_natural SET TABLESPACE tbs_recon_cold;
DROP INDEX IF EXISTS recon.ix_fact_leg_p20220408_created;
DROP INDEX IF EXISTS recon.ix_fact_leg_p20220408_source;

-- deny writes from app roles; Chris's audit role keeps SELECT
REVOKE INSERT, UPDATE, DELETE ON recon.fact_leg_p20220408 FROM recon_app, recon_match;

BEGIN;
SET lock_timeout = '8s';
SET statement_timeout = '8s';

DROP TRIGGER tg_fact_leg_dual ON recon.fact_leg;
DROP TRIGGER tg_break_header_dual ON recon.break_header;

LOCK TABLE recon.fact_leg, recon.fact_leg_new
    IN ACCESS EXCLUSIVE MODE;
LOCK TABLE recon.break_header, recon.break_header_new
    IN ACCESS EXCLUSIVE MODE;

ALTER TABLE recon.fact_leg RENAME TO fact_leg_legacy;
ALTER TABLE recon.fact_leg_new RENAME TO fact_leg;
ALTER TABLE recon.break_header RENAME TO break_header_legacy;
ALTER TABLE recon.break_header_new RENAME TO break_header;

-- sequences, grants, comments follow in the same tx (scripted in
-- tools/part_cutover.sql, reviewed by Rina May 16).
COMMIT;
